import{_ as t,o as d,c as a,a2 as s}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"Phase-one MVP acceptance","description":"Results, evidence, and open boundaries for 15 cross-industry real tasks.","frontmatter":{"title":"Phase-one MVP acceptance","description":"Results, evidence, and open boundaries for 15 cross-industry real tasks.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/mvp.md","filePath":"en/delivery/mvp.md","lastUpdated":null}'),r={name:"en/delivery/mvp.md"};function n(o,e,c,i,l,p){return d(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="phase-one-mvp-acceptance" tabindex="-1">Phase-one MVP acceptance <a class="header-anchor" href="#phase-one-mvp-acceptance" aria-label="Permalink to &quot;Phase-one MVP acceptance&quot;">​</a></h1><p class="lead">The phase-one exit was not &quot;the code is written&quot;. It was proving that one task path can execute, persist, request approval, produce artifacts, recover from failure, and back up data across 15 cross-industry real tasks.</p><h2 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Result</th></tr></thead><tbody><tr><td>Acceptance date</td><td>2026-11-05</td></tr><tr><td>Tasks</td><td>15</td></tr><tr><td>Passed</td><td>13 (T01–T06, T09–T15)</td></tr><tr><td>Artifacts passed, external approval pending</td><td>1 (T08)</td></tr><tr><td>Failed</td><td>1 (T07)</td></tr><tr><td>Hard gate</td><td>At least 10/15 passed; exceeded</td></tr></tbody></table><p>T07 and T08 were not used to pad the result. T07 ended <code>recoverable</code> with its failure evidence preserved; T08&#39;s GitHub comment approval is still <code>pending</code> with no external effect.</p><h2 id="per-task-results" tabindex="-1">Per-task results <a class="header-anchor" href="#per-task-results" aria-label="Permalink to &quot;Per-task results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Result</th><th>Evidence</th><th>Acceptance note</th></tr></thead><tbody><tr><td>T01</td><td>Passed</td><td><code>runs/T01/meeting-notes.md</code>, <code>run-manifest.json</code></td><td>Meeting transcript to action minutes with owners, dates, open questions, and source index</td></tr><tr><td>T02</td><td>Passed</td><td><code>runs/T02/clause-checklist.md</code>, <code>run-manifest.json</code></td><td>Contract clauses, obligations, page numbers, missing attachments, and amounts are checkable; no invented facts</td></tr><tr><td>T03</td><td>Passed</td><td><code>runs/T03/executive-summary.md</code>, <code>run-manifest.json</code></td><td>Multi-report merge preserves conflicts and sources instead of forcing agreement</td></tr><tr><td>T04</td><td>Passed</td><td><code>runs/T04/pages/</code>, <code>manifest.json</code>, <code>verification.md</code>, <code>run-manifest.json</code></td><td>Three URLs have status, final URL, fetch time, HTTP status, and SHA-256; the WCAG access failure is preserved as evidence</td></tr><tr><td>T05</td><td>Passed</td><td><code>runs/T05/competitor-comparison.md</code>, <code>run-manifest.json</code></td><td>Competitor pricing and features carry sources; undisclosed items are marked unknown</td></tr><tr><td>T06</td><td>Passed</td><td><code>runs/T06/policy-update-digest.md</code>, <code>run-manifest.json</code></td><td>Policy updates use official sources only; dates and change types are traceable</td></tr><tr><td>T07</td><td><strong>Failed</strong></td><td><code>runs/T07/report.md</code>, <code>pr-preview.json</code>, <code>run-manifest.json</code></td><td>Delivery validation blocked it: <code>backend/tests/unit/test_health_no_secrets.py</code> was uncommitted; no branch, no PR</td></tr><tr><td>T08</td><td>Artifacts passed, <strong>awaiting approval</strong></td><td><code>runs/T08/pr-review.md</code>, <code>run-manifest.json</code></td><td>PR #15 head pinned at <code>c007c4ed55345682689ac50bbafb090c5934c31a</code>; a 13 KB graded review was produced; comment approval is <code>pending</code>, <code>effectId</code> is <code>null</code></td></tr><tr><td>T09</td><td>Passed</td><td><code>runs/T09/bug-reproduction.md</code>, pytest outputs, exit codes, route evidence</td><td>Reproduced eight backend failures from PR #14; environment differences and unverified items preserved</td></tr><tr><td>T10</td><td>Passed</td><td><code>runs/T10/cleaned-sales.csv</code>, <code>exceptions.csv</code>, <code>change-log.md</code>, <code>summary.md</code></td><td>20-row sales cleanup; duplicates, missing values, and anomalies traceable; source unchanged</td></tr><tr><td>T11</td><td>Passed</td><td><code>runs/T11/expense-reconciliation.md</code>, <code>run-manifest.json</code></td><td>Seven line-by-line matches, 2640.00 total verified, exceptions complete</td></tr><tr><td>T12</td><td>Passed</td><td><code>runs/T12/triage.csv</code>, <code>reply-drafts.md</code>, <code>escalations.md</code>, <code>kb-draft.md</code></td><td>Eight tickets classified, redacted, escalated, and drafted; nothing sent</td></tr><tr><td>T13</td><td>Passed</td><td><code>runs/T13/job-description.md</code>, <code>interview-kit.md</code></td><td>No discriminatory criteria; interview kit and compliance check complete</td></tr><tr><td>T14</td><td>Passed</td><td><code>runs/T14/lesson-plan.md</code>, <code>quiz.md</code>, <code>answer-key.md</code></td><td>Lesson, quiz, and answer key are consistent and cover objectives and difficulty levels</td></tr><tr><td>T15</td><td>Passed</td><td><code>runs/T15/campaign-brief.md</code>, <code>asset-checklist.md</code></td><td>Claims grounded in inputs; three-channel asset list and approval state complete; nothing published</td></tr></tbody></table><h2 id="runtime-environment" tabindex="-1">Runtime environment <a class="header-anchor" href="#runtime-environment" aria-label="Permalink to &quot;Runtime environment&quot;">​</a></h2><ul><li>OS: Windows, PowerShell.</li><li>Node.js <code>v26.11.1</code>; npm <code>11.20.0</code>.</li><li>Control plane: Fastify + TypeScript; frontend: React + Vite.</li><li>Executor: native Codex adapter; active configuration <code>OpenDesign / deepseek-v4.1-flash</code>.</li><li>Auth source: <code>provider-env</code>; the key came from the terminal that started Hearth and was never sent to the browser.</li><li>Health: <code>GET /api/health</code> returned <code>canRun: true</code>, <code>authSource: &quot;provider-env&quot;</code>, <code>issues: []</code>.</li></ul><p>No <code>codex login</code> was required. If <code>~/.codex/config.toml</code> declares a <code>model_provider</code> and its <code>env_key</code>, and that variable exists in the starting terminal, Codex can run.</p><h2 id="g1–g9-acceptance-baseline" tabindex="-1">G1–G9 acceptance baseline <a class="header-anchor" href="#g1–g9-acceptance-baseline" aria-label="Permalink to &quot;G1–G9 acceptance baseline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Baseline</th><th>Evidence</th></tr></thead><tbody><tr><td>G1 Explicit input scope</td><td>Task templates and records include goal, input paths/URLs, and output directory; run manifests record input sources and SHA-256</td></tr><tr><td>G2 Visible state</td><td>State machine covers <code>queued</code>, <code>running</code>, <code>waiting_input</code>, <code>waiting_approval</code>, <code>completed</code>, <code>failed</code>, <code>recoverable</code>, <code>cancelled</code></td></tr><tr><td>G3 Durable results</td><td>Tasks, runs, approvals, effects, events, and artifact indexes are stored in <code>.hearth/hearth.sqlite</code> and survive restart</td></tr><tr><td>G4 Traceable artifacts</td><td>Every <code>run-manifest.json</code> records task/run ID, input digest, executor, generation time, and artifact SHA-256</td></tr><tr><td>G5 Controlled external actions</td><td>GitHub push, PR creation, and comments produce approval previews; T08 has no effect record</td></tr><tr><td>G6 No fabrication</td><td>T04 access challenge, T08 missing CI logs, and T09 host temp-directory issues are marked unknown or failed</td></tr><tr><td>G7 Recoverable failure</td><td>T07 ends <code>recoverable</code>, names the uncommitted file, and preserves the workspace</td></tr><tr><td>G8 Least authority</td><td>The service accepts loopback only and blocks cross-site writes; external writes require a one-time approval bound to a parameter fingerprint</td></tr><tr><td>G9 User-checkable</td><td>Tasks, detail, approval previews, artifact previews, and the in-app timeline are directly visible</td></tr></tbody></table><h2 id="automated-checks" tabindex="-1">Automated checks <a class="header-anchor" href="#automated-checks" aria-label="Permalink to &quot;Automated checks&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> test</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run typecheck</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run build </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">w @hearth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">web</span></span></code></pre></div><p>At acceptance time, <code>npm test</code> passed 51 tests, typecheck passed, and the web production build passed. After 2026-11-06 the suite grew to 40 files and 199 tests; the current baseline is in <a href="/hearth-os/en/delivery/acceptance.html">Acceptance and evidence</a>.</p><h2 id="what-this-acceptance-did-not-prove" tabindex="-1">What this acceptance did not prove <a class="header-anchor" href="#what-this-acceptance-did-not-prove" aria-label="Permalink to &quot;What this acceptance did not prove&quot;">​</a></h2><ul><li>It did not prove email, calendar, real sending, or high-risk desktop actions.</li><li>It did not prove mobile entry, proactive interruption control, or multi-device switching.</li><li>It did not prove multi-week operation, resource drift, or upgrade rollback.</li><li>It did not turn T07&#39;s failure or T08&#39;s pending approval into success.</li></ul><p>Raw per-task evidence lives in <code>eval/phase-1-acceptance.md</code> and <code>eval/runs/</code>.</p>`,18)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
